export const RHEN_SOURCE=Object.freeze({"/projects/rhen/source/evidence_journal.py":"\"\"\"ANEVUM V5 F1: append-only local evidence journal for PAPER research only.\n\nA self-contained successor package. No import from the legacy app, broker,\nRailway, Cloudflare, HTTP, trading, or public website code. A successful\nappend never represents proof that an entire upstream scan was captured or\nthat an off-host archive exists. Those are separate F2 gates.\n\"\"\"\nfrom __future__ import annotations\n\nfrom datetime import date, datetime, timezone\nfrom hashlib import sha256\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport re\nimport sqlite3\nfrom typing import Any, Mapping\nfrom zoneinfo import ZoneInfo\n\nSCHEMA_VERSION = \"anevum.decision-cycle.v1\"\nTRACKING_ID = \"ANEVUM.V5.FOUNDATION.2026-10-09.001\"\n_MAX_EVENT_BYTES = 4_000_000\n_MAX_CYCLES_PER_EXPORT = 3000\n_MAX_RUN_ROWS_VERIFIED = 100_000\n_ZERO_SHA = \"0\" * 64\n_HEX64 = re.compile(r\"^[0-9a-f]{64}$\")\n_WORKSPACE = re.compile(r\"^wrk_[A-Za-z0-9_-]{8,64}$\")\n_SYMBOL = re.compile(r\"^[A-Z][A-Z0-9.]{0,14}$\")\n_ID = re.compile(r\"^[A-Za-z0-9._:-]{1,128}$\")\n_EVENT_KEYS = {\n    \"schema_version\", \"workspace_id\", \"run_id\", \"cycle_id\", \"sequence_no\",\n    \"session_date\", \"occurred_at\", \"execution_mode\", \"strategy_version\",\n    \"config_sha256\", \"code_sha256\", \"market_source\", \"universe_symbols\",\n    \"candidates\",\n}\n_SOURCE_KEYS = {\n    \"feed\", \"data_status\", \"asof_timestamp\", \"universe_ref\",\n    \"bars_ref\", \"quotes_ref\",\n}\n_CANDIDATE_KEYS = {\n    \"symbol\", \"decision\", \"reason\", \"observed_at\", \"features\",\n}\n_DECISIONS = {\"QUALIFIED\", \"REJECTED\", \"UNMEASURABLE\"}\n_REJECTED_FEATURE_KEYS = (\n    \"token\", \"secret\", \"password\", \"authorization\", \"api_key\", \"credential\",\n    \"broker_account\", \"access_key\",\n)\n\n\nclass EvidenceContractError(ValueError):\n    \"\"\"Source observation is invalid or incomplete within its recorded cycle.\"\"\"\n\n\nclass EvidenceIntegrityError(RuntimeError):\n    \"\"\"A duplicate, gap, conflicting overwrite, or corrupted journal is found.\"\"\"\n\n\ndef _asof(value: Any, label: str) -> datetime:\n    if not isinstance(value, str) or not value:\n        raise EvidenceContractError(f\"{label} must have an explicit timezone\")\n    try:\n        result = datetime.fromisoformat(value.replace(\"Z\", \"+00:00\"))\n    except ValueError as exc:\n        raise EvidenceContractError(f\"{label} has invalid ISO timestamp\") from exc\n    if result.tzinfo is None:\n        raise EvidenceContractError(f\"{label} must have an explicit timezone\")\n    return result.astimezone(timezone.utc)\n\n\ndef _sha(value: Any, label: str) -> None:\n    if not isinstance(value, str) or not _HEX64.fullmatch(value):\n        raise EvidenceContractError(f\"{label} must be a lowercase SHA256 hex digest\")\n\n\ndef _id(value: Any, label: str) -> None:\n    if not isinstance(value, str) or not _ID.fullmatch(value):\n        raise EvidenceContractError(f\"{label} is missing or not a safe stable ID\")\n\n\ndef _json_bytes(value: Mapping[str, Any]) -> bytes:\n    try:\n        data = json.dumps(\n            value, sort_keys=True, ensure_ascii=False,\n            separators=(\",\", \":\"), allow_nan=False,\n        ).encode(\"utf-8\")\n    except (TypeError, ValueError) as exc:\n        raise EvidenceContractError(\"event cannot be canonicalized\") from exc\n    if len(data) > _MAX_EVENT_BYTES:\n        raise EvidenceContractError(\"event exceeds bounded journal envelope\")\n    return data\n\n\ndef validate_cycle(cycle: Mapping[str, Any]) -> bytes:\n    \"\"\"Validate one complete observed cycle; return exactly persisted bytes.\"\"\"\n    if not isinstance(cycle, dict) or set(cycle) != _EVENT_KEYS:\n        raise EvidenceContractError(\"cycle envelope fields do not match v1\")\n    if cycle[\"schema_version\"] != SCHEMA_VERSION:\n        raise EvidenceContractError(\"unknown decision-cycle schema version\")\n    if not isinstance(cycle[\"workspace_id\"], str) or not _WORKSPACE.fullmatch(cycle[\"workspace_id\"]):\n        raise EvidenceContractError(\"invalid workspace ID\")\n    _id(cycle[\"run_id\"], \"run_id\")\n    _id(cycle[\"cycle_id\"], \"cycle_id\")\n    sequence = cycle[\"sequence_no\"]\n    if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:\n        raise EvidenceContractError(\"sequence_no must be a positive integer\")\n    if cycle[\"execution_mode\"] != \"PAPER_RESEARCH_ONLY\":\n        raise EvidenceContractError(\"this journal forbids live execution\")\n    if not isinstance(cycle[\"strategy_version\"], str) or not 1 <= len(cycle[\"strategy_version\"]) <= 128:\n        raise EvidenceContractError(\"missing strategy version\")\n    _sha(cycle[\"config_sha256\"], \"config_sha256\")\n    _sha(cycle[\"code_sha256\"], \"code_sha256\")\n\n    occurred = _asof(cycle[\"occurred_at\"], \"occurred_at\")\n    try:\n        session = date.fromisoformat(cycle[\"session_date\"])\n    except (TypeError, ValueError) as exc:\n        raise EvidenceContractError(\"invalid session_date\") from exc\n    if session.isoformat() != cycle[\"session_date\"]:\n        raise EvidenceContractError(\"session_date must be YYYY-MM-DD\")\n    if occurred.astimezone(ZoneInfo(\"America/New_York\")).date() != session:\n        raise EvidenceContractError(\"session_date does not match New York observation\")\n\n    market = cycle[\"market_source\"]\n    if not isinstance(market, dict) or not {\"feed\", \"data_status\", \"asof_timestamp\", \"universe_ref\"} <= set(market):\n        raise EvidenceContractError(\"market source identity is missing\")\n    if not set(market) <= _SOURCE_KEYS:\n        raise EvidenceContractError(\"unrecognized market source fields\")\n    if not isinstance(market[\"feed\"], str) or not 1 <= len(market[\"feed\"]) <= 64:\n        raise EvidenceContractError(\"invalid market feed\")\n    if market[\"data_status\"] not in {\"COMPLETE\", \"PARTIAL\", \"UNAVAILABLE\"}:\n        raise EvidenceContractError(\"invalid market data status\")\n    market_at = _asof(market[\"asof_timestamp\"], \"market.asof_timestamp\")\n    if market_at > occurred:\n        raise EvidenceContractError(\"market data from the future\")\n    for name in (\"universe_ref\", \"bars_ref\", \"quotes_ref\"):\n        if name in market:\n            _sha(market[name], name)\n    if market[\"data_status\"] == \"COMPLETE\" and not {\"bars_ref\", \"quotes_ref\"} <= set(market):\n        raise EvidenceContractError(\"complete market state must identify raw bars and quotes\")\n\n    universe, candidates = cycle[\"universe_symbols\"], cycle[\"candidates\"]\n    if not isinstance(universe, list) or not isinstance(candidates, list):\n        raise EvidenceContractError(\"universe and full candidate population must be arrays\")\n    if len(universe) > 5000 or len(candidates) != len(universe):\n        raise EvidenceContractError(\"full candidate count must match universe size\")\n    if any(not isinstance(sym, str) or not _SYMBOL.fullmatch(sym) for sym in universe):\n        raise EvidenceContractError(\"invalid universe symbol\")\n    if len(set(universe)) != len(universe):\n        raise EvidenceContractError(\"duplicate universe symbols\")\n    observed_symbols = set()\n    for candidate in candidates:\n        if not isinstance(candidate, dict) or set(candidate) != _CANDIDATE_KEYS:\n            raise EvidenceContractError(\"candidate evidence fields incomplete\")\n        symbol = candidate[\"symbol\"]\n        if not isinstance(symbol, str) or not _SYMBOL.fullmatch(symbol) or symbol in observed_symbols:\n            raise EvidenceContractError(\"invalid or duplicate candidate symbol\")\n        observed_symbols.add(symbol)\n        if candidate[\"decision\"] not in _DECISIONS:\n            raise EvidenceContractError(\"candidate requires explicit disposition\")\n        if not isinstance(candidate[\"reason\"], str) or not 1 <= len(candidate[\"reason\"]) <= 512:\n            raise EvidenceContractError(\"candidate rejection/qualification reason missing\")\n        if _asof(candidate[\"observed_at\"], \"candidate.observed_at\") > occurred:\n            raise EvidenceContractError(\"candidate timestamp from the future\")\n        features = candidate[\"features\"]\n        if not isinstance(features, dict) or len(features) > 150:\n            raise EvidenceContractError(\"candidate feature vector malformed\")\n        for key, val in features.items():\n            if not isinstance(key, str) or not 1 <= len(key) <= 128:\n                raise EvidenceContractError(\"feature name malformed\")\n            if any(word in key.lower() for word in _REJECTED_FEATURE_KEYS):\n                raise EvidenceContractError(\"credential-like feature name rejected\")\n            if val is None or isinstance(val, bool):\n                continue\n            if isinstance(val, (int, float)) and not isinstance(val, bool):\n                if not math.isfinite(val):\n                    raise EvidenceContractError(\"nonfinite feature evidence\")\n            elif isinstance(val, str) and len(val) <= 1024:\n                continue\n            else:\n                raise EvidenceContractError(\"unsupported feature value\")\n    if observed_symbols != set(universe):\n        raise EvidenceContractError(\"candidate population omits or adds a universe symbol\")\n    return _json_bytes(cycle)\n\n\nclass DecisionJournal:\n    \"\"\"Account-scoped single-writer SQLite WAL; immutable committed source rows.\n\n    Protected against torn inserts, mutation and silent sequence gaps.\n    This is *not* a trading broker, R2 archive, or completeness authority.\n    \"\"\"\n\n    def __init__(self, db_path: str | Path):\n        self.path = Path(db_path)\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        if not self.path.exists():\n            try:\n                fd = os.open(str(self.path), os.O_WRONLY | os.O_CREAT | os.O_EXCL, 0o600)\n                os.close(fd)\n            except FileExistsError:\n                pass\n        self.conn = sqlite3.connect(str(self.path), timeout=10, isolation_level=None)\n        self.conn.execute(\"PRAGMA journal_mode=WAL\")\n        self.conn.execute(\"PRAGMA synchronous=FULL\")\n        self.conn.execute(\"PRAGMA busy_timeout=10000\")\n        self.conn.execute(\n            \"\"\"CREATE TABLE IF NOT EXISTS decision_journal(\n                workspace_id TEXT NOT NULL,\n                run_id TEXT NOT NULL,\n                sequence_no INTEGER NOT NULL,\n                cycle_id TEXT NOT NULL,\n                session_date TEXT NOT NULL,\n                payload_json TEXT NOT NULL,\n                payload_sha256 TEXT NOT NULL,\n                chain_sha256 TEXT NOT NULL,\n                archive_state TEXT NOT NULL DEFAULT 'PENDING_OFFHOST_ARCHIVE',\n                PRIMARY KEY(workspace_id, run_id, sequence_no),\n                UNIQUE(workspace_id, run_id, cycle_id)\n            )\"\"\"\n        )\n        self.conn.execute(\n            \"CREATE INDEX IF NOT EXISTS decision_session ON \"\n            \"decision_journal(workspace_id,run_id,session_date,sequence_no)\"\n        )\n\n    def close(self) -> None:\n        self.conn.close()\n\n    def __enter__(self) -> \"DecisionJournal\":\n        return self\n\n    def __exit__(self, *_args: object) -> None:\n        self.close()\n\n    def append_cycle(self, cycle: Mapping[str, Any]) -> dict[str, Any]:\n        raw = validate_cycle(cycle)\n        payload_sha = sha256(raw).hexdigest()\n        workspace, run, number, cycle_id = (\n            cycle[\"workspace_id\"], cycle[\"run_id\"],\n            cycle[\"sequence_no\"], cycle[\"cycle_id\"],\n        )\n        self.conn.execute(\"BEGIN IMMEDIATE\")\n        try:\n            duplicates = self.conn.execute(\n                \"SELECT sequence_no,cycle_id,payload_sha256,chain_sha256 FROM decision_journal \"\n                \"WHERE workspace_id=? AND run_id=? AND (sequence_no=? OR cycle_id=?)\",\n                (workspace, run, number, cycle_id),\n            ).fetchall()\n            if duplicates:\n                if (\n                    len(duplicates) == 1\n                    and duplicates[0][0] == number\n                    and duplicates[0][1] == cycle_id\n                    and duplicates[0][2] == payload_sha\n                ):\n                    self.conn.rollback()\n                    return {\n                        \"status\": \"ALREADY_RECORDED\", \"payload_sha256\": payload_sha,\n                        \"chain_sha256\": duplicates[0][3], \"sequence_no\": number,\n                        \"archive_state\": \"PENDING_OFFHOST_ARCHIVE\",\n                    }\n                raise EvidenceIntegrityError(\"conflicting cycle ID or sequence; overwrite forbidden\")\n            previous = self.conn.execute(\n                \"SELECT sequence_no,chain_sha256 FROM decision_journal \"\n                \"WHERE workspace_id=? AND run_id=? ORDER BY sequence_no DESC LIMIT 1\",\n                (workspace, run),\n            ).fetchone()\n            expected = 1 if previous is None else previous[0] + 1\n            if number != expected:\n                raise EvidenceIntegrityError(f\"sequence gap or rewind: expected {expected}, found {number}\")\n            prev_hash = _ZERO_SHA if previous is None else previous[1]\n            chain = sha256(bytes.fromhex(prev_hash) + bytes.fromhex(payload_sha)).hexdigest()\n            self.conn.execute(\n                \"INSERT INTO decision_journal (workspace_id,run_id,sequence_no,cycle_id,\"\n                \"session_date,payload_json,payload_sha256,chain_sha256) VALUES (?,?,?,?,?,?,?,?)\",\n                (workspace, run, number, cycle_id, cycle[\"session_date\"], raw.decode(), payload_sha, chain),\n            )\n            self.conn.commit()\n            return {\n                \"status\": \"RECORDED\", \"payload_sha256\": payload_sha,\n                \"chain_sha256\": chain, \"sequence_no\": number,\n                \"archive_state\": \"PENDING_OFFHOST_ARCHIVE\",\n            }\n        except Exception:\n            if self.conn.in_transaction:\n                self.conn.rollback()\n            raise\n\n    def export_session(\n        self, *, workspace_id: str, run_id: str, session_date: str,\n        independent_expected_cycle_count: int | None = None,\n    ) -> dict[str, Any]:\n        \"\"\"Validate the whole run's chain; return a *private* research export.\n\n        Does NOT attest that unobserved upstream cycles exist, that market refs\n        are uploaded, or that off-host R2 archival and restore have succeeded.\n        \"\"\"\n        if not _WORKSPACE.fullmatch(workspace_id) or not _ID.fullmatch(run_id):\n            raise EvidenceContractError(\"invalid scope\")\n        try:\n            if date.fromisoformat(session_date).isoformat() != session_date:\n                raise ValueError()\n        except (TypeError, ValueError) as exc:\n            raise EvidenceContractError(\"invalid session\") from exc\n        if independent_expected_cycle_count is not None and (\n            isinstance(independent_expected_cycle_count, bool)\n            or not isinstance(independent_expected_cycle_count, int)\n            or independent_expected_cycle_count < 0\n        ):\n            raise EvidenceContractError(\"invalid independent cycle count\")\n        cursor = self.conn.execute(\n            \"SELECT sequence_no,cycle_id,session_date,payload_json,payload_sha256,\"\n            \"chain_sha256,archive_state FROM decision_journal \"\n            \"WHERE workspace_id=? AND run_id=? ORDER BY sequence_no\",\n            (workspace_id, run_id),\n        )\n        previous = _ZERO_SHA\n        expected_seq = 1\n        checked = 0\n        events = []\n        raw_lines = []\n        quality_issues = []\n        for seq, cycle_id, stored_session, payload_json, payload_sha, chain_sha, archive_state in cursor:\n            checked += 1\n            if checked > _MAX_RUN_ROWS_VERIFIED:\n                raise EvidenceIntegrityError(\"run verification exceeds bounded limit\")\n            if seq != expected_seq:\n                raise EvidenceIntegrityError(\"run contains missing sequence\")\n            actual_payload_sha = sha256(payload_json.encode(\"utf-8\")).hexdigest()\n            if actual_payload_sha != payload_sha:\n                raise EvidenceIntegrityError(\"stored payload hash mismatch\")\n            actual_chain = sha256(bytes.fromhex(previous) + bytes.fromhex(payload_sha)).hexdigest()\n            if chain_sha != actual_chain:\n                raise EvidenceIntegrityError(\"chain integrity failure\")\n            payload = json.loads(payload_json)\n            if validate_cycle(payload) != payload_json.encode(\"utf-8\"):\n                raise EvidenceIntegrityError(\"stored payload is not canonical\")\n            if cycle_id != payload[\"cycle_id\"] or stored_session != payload[\"session_date\"]:\n                raise EvidenceIntegrityError(\"record provenance mismatch\")\n            if stored_session == session_date:\n                if len(events) >= _MAX_CYCLES_PER_EXPORT:\n                    raise EvidenceIntegrityError(\"session exceeds bounded export; never silently truncate\")\n                events.append(payload)\n                raw_lines.append(payload_json)\n                if payload[\"market_source\"][\"data_status\"] != \"COMPLETE\":\n                    quality_issues.append(f\"cycle:{seq}:MARKET_SOURCE_NOT_COMPLETE\")\n                if archive_state != \"ARCHIVED_VERIFIED\":\n                    quality_issues.append(f\"cycle:{seq}:OFFHOST_ARCHIVE_NOT_VERIFIED\")\n            expected_seq += 1\n            previous = chain_sha\n\n        if not events:\n            raise EvidenceIntegrityError(\"no events in requested session\")\n        if independent_expected_cycle_count is None:\n            quality_issues.append(\"INDEPENDENT_UPSTREAM_CYCLE_COUNT_MISSING\")\n        elif independent_expected_cycle_count != len(events):\n            quality_issues.append(\"INDEPENDENT_UPSTREAM_CYCLE_COUNT_MISMATCH\")\n        digest = sha256((\"\\n\".join(raw_lines) + \"\\n\").encode(\"utf-8\")).hexdigest()\n        manifest = {\n            \"schema_version\": \"anevum.evidence-export.v1\",\n            \"tracking_id\": TRACKING_ID,\n            \"scope\": {\"workspace_id\": workspace_id, \"run_id\": run_id, \"session_date\": session_date},\n            \"cycles_exported\": len(events),\n            \"candidates_exported\": sum(len(e[\"candidates\"]) for e in events),\n            \"rejected_exported\": sum(sum(c[\"decision\"] == \"REJECTED\" for c in e[\"candidates\"]) for e in events),\n            \"first_sequence\": events[0][\"sequence_no\"],\n            \"last_sequence\": events[-1][\"sequence_no\"],\n            \"journal_chain_verified\": True,\n            \"jsonl_sha256\": digest,\n            \"independent_cycle_count\": independent_expected_cycle_count,\n            \"quality_issues\": sorted(set(quality_issues)),\n            \"source_completeness\": \"AWAITING_OFFHOST_ARCHIVE_AND_UPSTREAM_ATTESTATION\",\n            \"full_population_across_all_cycles_proven\": False,\n            \"alpha_validated\": False,\n            \"broker_write_authority\": False,\n        }\n        return {\"manifest\": manifest, \"private_cycles\": events}\n","/projects/rhen/source/source_attestation.py":"\"\"\"ANEVUM V5 F3a: separate scanner-origin source ledger and local audit.\n\nThis is a PAPER_RESEARCH_ONLY development contract, not a production scanner.\nThe scanner must persist its manifest BEFORE the decision journal write. There\nis intentionally no `manifest_from_journal()` helper: a circular proof made\nfrom journal events would not establish upstream completeness.\n\nLocal scanner and journal matching is not independent external source proof,\nmarket-bar/quote recovery, off-host archiving, or live trading authorization.\n\"\"\"\nfrom __future__ import annotations\n\nfrom datetime import date, datetime, timezone\nfrom hashlib import sha256\nimport json\nimport math\nimport os\nfrom pathlib import Path\nimport re\nimport sqlite3\nfrom typing import Any, Mapping, Protocol\nfrom zoneinfo import ZoneInfo\n\nSOURCE_SCHEMA = \"anevum.scanner-source.v1\"\nTRACKING_ID = \"ANEVUM.V5.FOUNDATION.2026-10-09.001\"\nMAX_SCANS_PER_SESSION = 3000\nMAX_ROWS_PER_RUN = 100000\nMAX_MANIFEST_BYTES = 1500000\nMAX_REPORTED_ISSUES = 32\nZERO_HASH = \"0\" * 64\nSHA_PATTERN = re.compile(r\"^[0-9a-f]{64}$\")\nWORKSPACE_PATTERN = re.compile(r\"^wrk_[A-Za-z0-9_-]{8,64}$\")\nID_PATTERN = re.compile(r\"^[A-Za-z0-9._:-]{1,128}$\")\nSYMBOL_PATTERN = re.compile(r\"^[A-Z][A-Z0-9.]{0,14}$\")\n\nFIELDS = {\n    \"schema_version\", \"workspace_id\", \"run_id\", \"cycle_id\", \"sequence_no\",\n    \"session_date\", \"occurred_at\", \"scan_origin\", \"strategy_version\",\n    \"config_sha256\", \"code_sha256\", \"market_source_sha256\",\n    \"universe_symbols\", \"evaluations\",\n}\nEVALUATION_FIELDS = {\n    \"symbol\", \"decision\", \"reason\", \"observed_at\", \"features_sha256\",\n}\nDECISIONS = {\"QUALIFIED\", \"REJECTED\", \"UNMEASURABLE\"}\nSCAN_ORIGINS = {\"SYNTHETIC_FIXTURE\", \"PRE_JOURNAL_SCANNER\"}\n\n\nclass SourceContractError(ValueError):\n    \"\"\"Invalid or unscoped scanner-source observation.\"\"\"\n\n\nclass SourceIntegrityError(RuntimeError):\n    \"\"\"Missing, changed, contradictory or corrupted scanner-source records.\"\"\"\n\n\ndef canonical(value: Any) -> bytes:\n    try:\n        raw = json.dumps(value, sort_keys=True, separators=(\",\", \":\"),\n                         ensure_ascii=False, allow_nan=False).encode(\"utf-8\")\n    except (ValueError, TypeError, OverflowError) as exc:\n        raise SourceContractError(\"unable to canonicalize source\") from exc\n    if len(raw) > MAX_MANIFEST_BYTES:\n        raise SourceContractError(\"scanner manifest exceeds bounded size\")\n    return raw\n\n\ndef digest(value: Any) -> str:\n    return sha256(canonical(value)).hexdigest()\n\n\ndef _timestamp(value: Any, label: str) -> datetime:\n    if not isinstance(value, str) or not value:\n        raise SourceContractError(f\"{label} requires a timezone\")\n    try:\n        result = datetime.fromisoformat(value.replace(\"Z\", \"+00:00\"))\n    except ValueError as exc:\n        raise SourceContractError(f\"{label} must be ISO-8601\") from exc\n    if result.tzinfo is None:\n        raise SourceContractError(f\"{label} requires a timezone\")\n    return result.astimezone(timezone.utc)\n\n\ndef _validate_scope(workspace_id: str, run_id: str, session_date: str) -> None:\n    if not isinstance(workspace_id, str) or not WORKSPACE_PATTERN.fullmatch(workspace_id):\n        raise SourceContractError(\"invalid scanner workspace\")\n    if not isinstance(run_id, str) or not ID_PATTERN.fullmatch(run_id):\n        raise SourceContractError(\"invalid scanner run\")\n    if not isinstance(session_date, str):\n        raise SourceContractError(\"invalid scanner session\")\n    try:\n        if date.fromisoformat(session_date).isoformat() != session_date:\n            raise ValueError(\"noncanonical date\")\n    except ValueError as exc:\n        raise SourceContractError(\"invalid scanner session\") from exc\n\n\ndef validate_scan(manifest: Mapping[str, Any]) -> bytes:\n    if not isinstance(manifest, dict) or set(manifest) != FIELDS:\n        raise SourceContractError(\"scanner manifest contract mismatch\")\n    if manifest[\"schema_version\"] != SOURCE_SCHEMA:\n        raise SourceContractError(\"unsupported scanner manifest schema\")\n    _validate_scope(manifest[\"workspace_id\"], manifest[\"run_id\"],\n                    manifest[\"session_date\"])\n    if not isinstance(manifest[\"cycle_id\"], str) or not ID_PATTERN.fullmatch(manifest[\"cycle_id\"]):\n        raise SourceContractError(\"invalid scanner cycle identity\")\n    sequence = manifest[\"sequence_no\"]\n    if isinstance(sequence, bool) or not isinstance(sequence, int) or sequence < 1:\n        raise SourceContractError(\"invalid scanner sequence\")\n    if not isinstance(manifest[\"scan_origin\"], str) or manifest[\"scan_origin\"] not in SCAN_ORIGINS:\n        raise SourceContractError(\"unknown scanner origin\")\n    occurred = _timestamp(manifest[\"occurred_at\"], \"scanner occurred_at\")\n    if occurred.astimezone(ZoneInfo(\"America/New_York\")).date().isoformat() != manifest[\"session_date\"]:\n        raise SourceContractError(\"scanner occurred_at is outside declared ET session\")\n    if not isinstance(manifest[\"strategy_version\"], str) or not 1 <= len(manifest[\"strategy_version\"]) <= 128:\n        raise SourceContractError(\"invalid scanner strategy version\")\n    for key in (\"config_sha256\", \"code_sha256\", \"market_source_sha256\"):\n        if not isinstance(manifest[key], str) or not SHA_PATTERN.fullmatch(manifest[key]):\n            raise SourceContractError(\"invalid scanner provenance digest\")\n    symbols, evaluations = manifest[\"universe_symbols\"], manifest[\"evaluations\"]\n    if not isinstance(symbols, list) or not isinstance(evaluations, list):\n        raise SourceContractError(\"scanner must provide full symbol/evaluation arrays\")\n    if len(symbols) > 5000 or len(symbols) != len(evaluations):\n        raise SourceContractError(\"scanner evaluations must equal source universe\")\n    if any(not isinstance(s, str) or not SYMBOL_PATTERN.fullmatch(s) for s in symbols):\n        raise SourceContractError(\"invalid scanner symbol\")\n    if len(set(symbols)) != len(symbols):\n        raise SourceContractError(\"duplicate scanner universe symbol\")\n    seen: set[str] = set()\n    for evaluation in evaluations:\n        if not isinstance(evaluation, dict) or set(evaluation) != EVALUATION_FIELDS:\n            raise SourceContractError(\"incomplete scanner disposition\")\n        symbol = evaluation[\"symbol\"]\n        if not isinstance(symbol, str) or not SYMBOL_PATTERN.fullmatch(symbol) or symbol in seen:\n            raise SourceContractError(\"duplicate or invalid scanner disposition symbol\")\n        seen.add(symbol)\n        if not isinstance(evaluation[\"decision\"], str) or evaluation[\"decision\"] not in DECISIONS:\n            raise SourceContractError(\"invalid scanner candidate disposition\")\n        if not isinstance(evaluation[\"reason\"], str) or not 1 <= len(evaluation[\"reason\"]) <= 512:\n            raise SourceContractError(\"missing scanner disposition reason\")\n        if _timestamp(evaluation[\"observed_at\"], \"scanner candidate observed_at\") > occurred:\n            raise SourceContractError(\"scanner candidate observed in the future\")\n        value = evaluation[\"features_sha256\"]\n        if not isinstance(value, str) or not SHA_PATTERN.fullmatch(value):\n            raise SourceContractError(\"missing scanner feature provenance\")\n    if seen != set(symbols):\n        raise SourceContractError(\"scanner omitted a universe disposition\")\n    return canonical(manifest)\n\n\nclass SourceScanLedger:\n    \"\"\"Independent SQLite/WAL record of scanner-origin manifests.\n\n    Must be a distinct DB file from the decision journal and fed upstream,\n    not by re-exporting/deriving recorded decision journal rows.\n    \"\"\"\n\n    def __init__(self, db_path: str | Path):\n        self.path = Path(db_path).resolve()\n        self.path.parent.mkdir(parents=True, exist_ok=True)\n        if not self.path.exists():\n            try:\n                fd = os.open(self.path, os.O_WRONLY | os.O_EXCL | os.O_CREAT, 0o600)\n                os.close(fd)\n            except FileExistsError:\n                pass\n        self.conn = sqlite3.connect(self.path, timeout=10, isolation_level=None)\n        self.conn.execute(\"PRAGMA journal_mode=WAL\")\n        self.conn.execute(\"PRAGMA synchronous=FULL\")\n        self.conn.execute(\"PRAGMA busy_timeout=10000\")\n        self.conn.execute(\"\"\"CREATE TABLE IF NOT EXISTS source_scans (\n            workspace_id TEXT NOT NULL, run_id TEXT NOT NULL,\n            sequence_no INTEGER NOT NULL, cycle_id TEXT NOT NULL,\n            session_date TEXT NOT NULL, manifest_json TEXT NOT NULL,\n            manifest_sha256 TEXT NOT NULL, chain_sha256 TEXT NOT NULL,\n            PRIMARY KEY(workspace_id, run_id, sequence_no),\n            UNIQUE(workspace_id, run_id, cycle_id)\n        )\"\"\")\n\n    def close(self) -> None:\n        self.conn.close()\n\n    def __enter__(self) -> \"SourceScanLedger\":\n        return self\n\n    def __exit__(self, *_args: Any) -> None:\n        self.close()\n\n    def record_scan(self, manifest: Mapping[str, Any]) -> dict[str, Any]:\n        raw = validate_scan(manifest)\n        manifest_sha = sha256(raw).hexdigest()\n        workspace, run, sequence, cycle_id = (\n            manifest[\"workspace_id\"], manifest[\"run_id\"],\n            manifest[\"sequence_no\"], manifest[\"cycle_id\"],\n        )\n        self.conn.execute(\"BEGIN IMMEDIATE\")\n        try:\n            duplicates = self.conn.execute(\n                \"SELECT sequence_no,cycle_id,manifest_sha256,chain_sha256 FROM source_scans \"\n                \"WHERE workspace_id=? AND run_id=? AND (sequence_no=? OR cycle_id=?)\",\n                (workspace, run, sequence, cycle_id),\n            ).fetchall()\n            if duplicates:\n                if (len(duplicates) == 1 and duplicates[0][0] == sequence and\n                        duplicates[0][1] == cycle_id and duplicates[0][2] == manifest_sha):\n                    self.conn.rollback()\n                    return {\"status\": \"ALREADY_RECORDED\", \"manifest_sha256\": manifest_sha,\n                            \"chain_sha256\": duplicates[0][3]}\n                raise SourceIntegrityError(\"scanner cycle conflicts with immutable source\")\n            prev = self.conn.execute(\n                \"SELECT sequence_no,chain_sha256 FROM source_scans \"\n                \"WHERE workspace_id=? AND run_id=? ORDER BY sequence_no DESC LIMIT 1\",\n                (workspace, run),\n            ).fetchone()\n            expected = 1 if prev is None else prev[0] + 1\n            if sequence != expected:\n                raise SourceIntegrityError(\"scanner sequence gap or rewind\")\n            chain = sha256(bytes.fromhex(ZERO_HASH if prev is None else prev[1]) +\n                           bytes.fromhex(manifest_sha)).hexdigest()\n            self.conn.execute(\n                \"INSERT INTO source_scans VALUES (?,?,?,?,?,?,?,?)\",\n                (workspace, run, sequence, cycle_id, manifest[\"session_date\"],\n                 raw.decode(\"utf-8\"), manifest_sha, chain),\n            )\n            self.conn.commit()\n            return {\"status\": \"SCANNER_RECORDED\", \"manifest_sha256\": manifest_sha,\n                    \"chain_sha256\": chain}\n        except Exception:\n            if self.conn.in_transaction:\n                self.conn.rollback()\n            raise\n\n    def read_session_verified(self, *, workspace_id: str, run_id: str,\n                              session_date: str) -> dict[str, Any]:\n        _validate_scope(workspace_id, run_id, session_date)\n        cursor = self.conn.execute(\n            \"SELECT sequence_no,cycle_id,session_date,manifest_json,manifest_sha256,chain_sha256 \"\n            \"FROM source_scans WHERE workspace_id=? AND run_id=? ORDER BY sequence_no\",\n            (workspace_id, run_id),\n        )\n        previous, expected = ZERO_HASH, 1\n        count, session_scans = 0, []\n        raw_session_lines: list[str] = []\n        for sequence, cycle_id, session, source_json, payload_sha, chain_sha in cursor:\n            count += 1\n            if count > MAX_ROWS_PER_RUN:\n                raise SourceIntegrityError(\"scanner run exceeds verification bounds\")\n            if sequence != expected:\n                raise SourceIntegrityError(\"scanner run contains a missing sequence\")\n            if (not isinstance(payload_sha, str) or not SHA_PATTERN.fullmatch(payload_sha)\n                    or not isinstance(chain_sha, str) or not SHA_PATTERN.fullmatch(chain_sha)):\n                raise SourceIntegrityError(\"scanner source digest malformed\")\n            if sha256(source_json.encode(\"utf-8\")).hexdigest() != payload_sha:\n                raise SourceIntegrityError(\"scanner source payload checksum changed\")\n            if sha256(bytes.fromhex(previous) + bytes.fromhex(payload_sha)).hexdigest() != chain_sha:\n                raise SourceIntegrityError(\"scanner source chain changed\")\n            try:\n                event = json.loads(source_json)\n                if validate_scan(event) != source_json.encode(\"utf-8\"):\n                    raise SourceIntegrityError(\"scanner source JSON is not canonical\")\n            except (SourceContractError, ValueError, TypeError) as exc:\n                raise SourceIntegrityError(\"scanner stored event is invalid\") from exc\n            if (event[\"workspace_id\"] != workspace_id or event[\"run_id\"] != run_id or\n                    event[\"cycle_id\"] != cycle_id or event[\"sequence_no\"] != sequence or\n                    event[\"session_date\"] != session):\n                raise SourceIntegrityError(\"scanner source scope mismatches index\")\n            if session == session_date:\n                if len(session_scans) >= MAX_SCANS_PER_SESSION:\n                    raise SourceIntegrityError(\"scanner session exceeds explicit verification bounds\")\n                session_scans.append(event)\n                raw_session_lines.append(source_json)\n            previous, expected = chain_sha, expected + 1\n        return {\n            \"scans\": session_scans,\n            \"source_run_chain_sha256\": previous,\n            \"source_session_jsonl_sha256\": sha256((\"\\n\".join(raw_session_lines) + \"\\n\").encode()).hexdigest(),\n            \"scanned_run_records\": count,\n        }\n\n\nclass DecisionSessionReader(Protocol):\n    path: Path\n    def export_session(self, *, workspace_id: str, run_id: str,\n                       session_date: str) -> Mapping[str, Any]: ...\n\n\ndef _issue_summary(issues: list[str]) -> dict[str, Any]:\n    unique = sorted(set(issues))\n    return {\"issue_codes\": unique[:MAX_REPORTED_ISSUES],\n            \"issue_count\": len(unique),\n            \"issues_truncated\": len(unique) > MAX_REPORTED_ISSUES}\n\n\ndef verify_scan_population(\n    source: SourceScanLedger, journal: DecisionSessionReader, *,\n    workspace_id: str, run_id: str, session_date: str,\n    scheduler_expected_cycles: int | None = None,\n    trusted_source_chain_sha256: str | None = None,\n) -> dict[str, Any]:\n    \"\"\"Reconcile all source scanner cycles versus a verified journal export.\n\n    Neither the source ledger itself nor caller-provided digests prove that a\n    real scanner/scheduler emitted every scheduled cycle. F3a always returns\n    AWAITING_EVIDENCE for matching local-only input, BLOCKED for violations.\n    \"\"\"\n    _validate_scope(workspace_id, run_id, session_date)\n    if scheduler_expected_cycles is not None and (isinstance(scheduler_expected_cycles, bool) or\n            not isinstance(scheduler_expected_cycles, int) or scheduler_expected_cycles < 0):\n        raise SourceContractError(\"invalid independent scheduler cycle count\")\n    if trusted_source_chain_sha256 is not None and (not isinstance(trusted_source_chain_sha256, str)\n            or not SHA_PATTERN.fullmatch(trusted_source_chain_sha256)):\n        raise SourceContractError(\"invalid independent source digest\")\n    if Path(source.path).resolve() == Path(journal.path).resolve():\n        raise SourceContractError(\"scanner ledger must not share journal DB file\")\n    issues: list[str] = []\n    source_scans: list[dict[str, Any]] = []\n    source_chain: str | None = None\n    journal_cycles: list[dict[str, Any]] = []\n    journal_sha: str | None = None\n    try:\n        report = source.read_session_verified(\n            workspace_id=workspace_id, run_id=run_id, session_date=session_date)\n        source_scans = report[\"scans\"]\n        source_chain = report[\"source_run_chain_sha256\"]\n    except (SourceIntegrityError, SourceContractError, sqlite3.DatabaseError):\n        issues.append(\"SCANNER_LEDGER_INTEGRITY_BLOCKED\")\n    try:\n        exported = journal.export_session(\n            workspace_id=workspace_id, run_id=run_id, session_date=session_date)\n        manifest = exported[\"manifest\"]\n        journal_cycles = exported[\"private_cycles\"]\n        journal_sha = manifest[\"jsonl_sha256\"]\n        if (manifest.get(\"journal_chain_verified\") is not True or\n                manifest.get(\"cycles_exported\") != len(journal_cycles)):\n            issues.append(\"JOURNAL_CHAIN_OR_COUNT_NOT_VERIFIED\")\n    except (RuntimeError, ValueError, sqlite3.DatabaseError, KeyError, TypeError):\n        issues.append(\"JOURNAL_EXPORT_INTEGRITY_BLOCKED\")\n\n    if not source_scans:\n        issues.append(\"SCANNER_SOURCE_MISSING\")\n    if not journal_cycles:\n        issues.append(\"JOURNAL_SESSION_MISSING\")\n    source_seq = {s[\"sequence_no\"]: s for s in source_scans}\n    journal_seq = {j[\"sequence_no\"]: j for j in journal_cycles}\n    for seq in sorted(source_seq.keys() - journal_seq.keys()):\n        issues.append(f\"JOURNAL_MISSING_SCANNER_CYCLE:{seq}\")\n    for seq in sorted(journal_seq.keys() - source_seq.keys()):\n        issues.append(f\"SCANNER_MISSING_JOURNAL_CYCLE:{seq}\")\n    compared_candidates = 0\n    for seq in sorted(source_seq.keys() & journal_seq.keys()):\n        scan, row = source_seq[seq], journal_seq[seq]\n        expected_fields = (\n            (\"workspace_id\", \"SCOPE\"), (\"run_id\", \"RUN\"),\n            (\"cycle_id\", \"CYCLE_ID\"), (\"sequence_no\", \"SEQUENCE\"),\n            (\"session_date\", \"SESSION\"), (\"occurred_at\", \"OBSERVATION_TIME\"),\n            (\"strategy_version\", \"STRATEGY\"), (\"config_sha256\", \"CONFIG\"),\n            (\"code_sha256\", \"CODE\"), (\"universe_symbols\", \"UNIVERSE\"),\n        )\n        for field, label in expected_fields:\n            if scan.get(field) != row.get(field):\n                issues.append(f\"SOURCE_JOURNAL_{label}_MISMATCH:{seq}\")\n        if scan[\"market_source_sha256\"] != digest(row[\"market_source\"]):\n            issues.append(f\"MARKET_SOURCE_PROVENANCE_MISMATCH:{seq}\")\n        scans = scan[\"evaluations\"]\n        rows = row.get(\"candidates\", [])\n        if not isinstance(rows, list) or len(scans) != len(rows):\n            issues.append(f\"CANDIDATE_COUNT_MISMATCH:{seq}\")\n            continue\n        compared_candidates += len(scans)\n        for scanned, candidate in zip(scans, rows):\n            if not isinstance(candidate, dict):\n                issues.append(f\"CANDIDATE_RECORD_INVALID:{seq}\")\n                continue\n            if scanned[\"symbol\"] != candidate.get(\"symbol\"):\n                issues.append(f\"CANDIDATE_ORDER_OR_SYMBOL_MISMATCH:{seq}\")\n            for field in (\"decision\", \"reason\", \"observed_at\"):\n                if scanned[field] != candidate.get(field):\n                    issues.append(f\"CANDIDATE_{field.upper()}_MISMATCH:{seq}\")\n            try:\n                features_sha = digest(candidate.get(\"features\"))\n            except (SourceContractError, ValueError, TypeError):\n                features_sha = None\n            if scanned[\"features_sha256\"] != features_sha:\n                issues.append(f\"CANDIDATE_FEATURES_MISMATCH:{seq}\")\n    if scheduler_expected_cycles is None:\n        issues.append(\"SCHEDULER_CYCLE_COUNT_NOT_ATTESTED\")\n    elif scheduler_expected_cycles != len(source_scans) or scheduler_expected_cycles != len(journal_cycles):\n        issues.append(\"INDEPENDENT_SCHEDULER_COUNT_MISMATCH\")\n    if trusted_source_chain_sha256 is None:\n        issues.append(\"EXTERNAL_SCANNER_DIGEST_NOT_PINNED\")\n    elif source_chain != trusted_source_chain_sha256:\n        issues.append(\"EXTERNAL_SCANNER_CHAIN_DIGEST_MISMATCH\")\n    if any(s[\"scan_origin\"] == \"SYNTHETIC_FIXTURE\" for s in source_scans):\n        issues.append(\"SYNTHETIC_SCANNER_SOURCE_NOT_MARKET_EVIDENCE\")\n    issues.append(\"UPSTREAM_SCANNER_INTEGRATION_NOT_ATTESTED\")\n    issues.append(\"RAW_MARKET_OBJECTS_NOT_VERIFIED\")\n    issues.append(\"R2_ARCHIVE_COMPLETENESS_NOT_VERIFIED\")\n    blocking = any(x.startswith((\n        \"SCANNER_LEDGER_\", \"JOURNAL_\", \"SCANNER_SOURCE_MISSING\",\n        \"SCANNER_MISSING\", \"SOURCE_JOURNAL_\", \"MARKET_SOURCE_PROVENANCE_\",\n        \"CANDIDATE_\", \"INDEPENDENT_SCHEDULER_COUNT_MISMATCH\",\n        \"EXTERNAL_SCANNER_CHAIN_DIGEST_MISMATCH\",\n    )) for x in issues)\n    state = \"BLOCKED\" if blocking else \"AWAITING_EVIDENCE\"\n    manifest = {\n        \"schema_version\": \"anevum.scan-reconciliation.v1\",\n        \"tracking_id\": TRACKING_ID,\n        \"scope\": {\"workspace_id\": workspace_id, \"run_id\": run_id,\n                  \"session_date\": session_date},\n        \"scanner_cycles\": len(source_scans),\n        \"journal_cycles\": len(journal_cycles),\n        \"candidate_count_compared\": compared_candidates,\n        \"source_only_cycles\": len(source_seq.keys() - journal_seq.keys()),\n        \"journal_only_cycles\": len(journal_seq.keys() - source_seq.keys()),\n        \"source_ledger_chain_sha256\": source_chain,\n        \"journal_session_sha256\": journal_sha,\n        \"scheduler_expected_cycles\": scheduler_expected_cycles,\n        \"source_digest_externally_provided\": trusted_source_chain_sha256 is not None,\n        \"scanner_journal_population_agrees\": not blocking and bool(source_scans),\n        \"upstream_origin_independently_attested\": False,\n        \"raw_market_objects_verified\": False,\n        \"offhost_archive_verified\": False,\n        \"full_population_across_upstream_proven\": False,\n        \"research_ready\": False,\n        \"alpha_validated\": False,\n        \"broker_write_authority\": False,\n        \"evidence_state\": state,\n        **_issue_summary(issues),\n    }\n    manifest[\"reconciliation_sha256\"] = digest(manifest)\n    return manifest\n","/projects/rhen/source/paper_market_feed.py":"\"\"\"ANEVUM V5 F3c - bounded, read-only Alpaca equity market-data ingest.\n\nOnly two historical data GET routes are callable, never order/account routes.\nNo network call is made on import or without explicitly supplied credentials.\nThe output remains UNATTESTED_IMPORTED even after authenticated HTTPS 200:\nneither provider entitlement nor upstream minute coverage is cryptographically\nattested, and no paper/live brokerage execution is authorized.\n\"\"\"\nfrom __future__ import annotations\n\nfrom datetime import datetime, timedelta, timezone\nfrom hashlib import sha256\nimport json\nimport re\nfrom typing import Any, Mapping, Protocol\nfrom urllib.parse import urlencode\nfrom urllib.request import Request, HTTPRedirectHandler, build_opener\n\nfrom .paper_capture import (\n    SNAPSHOT_SCHEMA, _utc, validate_snapshot, PaperCaptureError,\n)\nfrom .paper_schedule import validate_slot\n\nHOST = \"data.alpaca.markets\"\nBARS_PATH = \"/v2/stocks/bars\"\nQUOTES_PATH = \"/v2/stocks/quotes\"\nPATHS = {BARS_PATH, QUOTES_PATH}\nFEEDS = {\"iex\", \"sip\"}\nMAX_SYMBOLS = 10\nMAX_PAGES_PER_ENDPOINT = 4\nMAX_ITEMS = 1200\nMAX_BODY_BYTES = 256_000\nMAX_RESPONSE_BYTES = 1_000_000\nTIMEOUT_SECONDS = 8\nPAGE_LIMIT = 300\nQUOTE_SAMPLE_LIMIT = 1\nQUOTE_SAMPLING_MODE = \"PER_SYMBOL_DESC_LATEST_ASOF_V1\"\nMAX_TOTAL_PAGES = MAX_PAGES_PER_ENDPOINT + MAX_SYMBOLS\n\n\nclass MarketFeedError(RuntimeError):\n    \"\"\"Unsafe, unavailable, malformed or incomplete provider retrieval.\"\"\"\n\n\ndef _json(value: Any) -> bytes:\n    try:\n        result = json.dumps(value, sort_keys=True, separators=(\",\", \":\"),\n                            allow_nan=False, ensure_ascii=False).encode(\"utf-8\")\n    except (TypeError, ValueError, OverflowError) as exc:\n        raise MarketFeedError(\"provider response is not canonical JSON\") from exc\n    if len(result) > MAX_RESPONSE_BYTES:\n        raise MarketFeedError(\"provider evidence exceeds bounded size\")\n    return result\n\n\nclass PageReader(Protocol):\n    def get(self, *, path: str, params: Mapping[str, str]) -> dict[str, Any]: ...\n\n\nclass _RejectRedirects(HTTPRedirectHandler):\n    def redirect_request(self, *_args: Any, **_kwargs: Any) -> None:\n        return None\n\n\nclass AlpacaHTTPSReadOnly:\n    \"\"\"Opt-in HTTPS data transport with fixed host, fixed routes and no redirects.\n\n    Credentials must be injected at runtime from a dedicated, narrowly scoped\n    paper-data environment; do NOT reuse Alpaca Connect OAuth app secrets.\n    Although this class cannot issue orders, an account key could have broad\n    provider permissions. Actual key privileges must be verified separately.\n    \"\"\"\n\n    def __init__(self, *, key_id: str, secret_key: str, opener: Any = None):\n        if (not isinstance(key_id, str) or not key_id.strip() or\n                not isinstance(secret_key, str) or not secret_key.strip()):\n            raise MarketFeedError(\"separate paper-data API credentials required\")\n        self._key_id, self._secret = key_id, secret_key\n        self._opener = opener if opener is not None else build_opener(_RejectRedirects())\n        self.requests = 0\n\n    def get(self, *, path: str, params: Mapping[str, str]) -> dict[str, Any]:\n        if path not in PATHS:\n            raise MarketFeedError(\"read-only route is not permitted\")\n        if not isinstance(params, dict) or set(params) not in (\n                {\"symbols\",\"timeframe\",\"start\",\"end\",\"feed\",\"limit\",\"sort\"},\n                {\"symbols\",\"timeframe\",\"start\",\"end\",\"feed\",\"limit\",\"sort\",\"page_token\"},\n                {\"symbols\",\"start\",\"end\",\"feed\",\"limit\",\"sort\"},\n                {\"symbols\",\"start\",\"end\",\"feed\",\"limit\",\"sort\",\"page_token\"},\n        ):\n            raise MarketFeedError(\"unexpected market-data query parameters\")\n        if ((path == BARS_PATH) != (\"timeframe\" in params)):\n            raise MarketFeedError(\"timeframe allowed for historical bars only\")\n        if any(not isinstance(v, str) or len(v) > 512 for v in params.values()):\n            raise MarketFeedError(\"query parameter exceeds bounds\")\n        if params.get(\"feed\") not in FEEDS:\n            raise MarketFeedError(\"feed contract mismatch\")\n        if path == BARS_PATH:\n            if (params.get(\"sort\") != \"asc\"\n                    or params.get(\"timeframe\") != \"1Min\"\n                    or params.get(\"limit\") != str(PAGE_LIMIT)):\n                raise MarketFeedError(\"unexpected bar timeframe, sort or page limit\")\n            requested = params.get(\"symbols\", \"\").split(\",\")\n        else:\n            if (params.get(\"sort\") != \"desc\"\n                    or params.get(\"limit\") != str(QUOTE_SAMPLE_LIMIT)\n                    or \"page_token\" in params):\n                raise MarketFeedError(\"latest quote requires one descending sample\")\n            requested = [params.get(\"symbols\", \"\")]\n        if (not 1 <= len(requested) <= MAX_SYMBOLS\n                or len(set(requested)) != len(requested)\n                or any(not re.fullmatch(r\"[A-Z][A-Z0-9.]{0,14}\", x)\n                       for x in requested)):\n            raise MarketFeedError(\"invalid or oversized market symbol scope\")\n        begin = _utc(params[\"start\"], \"provider start\")\n        end = _utc(params[\"end\"], \"provider end\")\n        if begin >= end:\n            raise MarketFeedError(\"market source time window invalid\")\n        url = \"https://\" + HOST + path + \"?\" + urlencode(params)\n        req = Request(\n            url, method=\"GET\",\n            headers={\"Accept\":\"application/json\",\n                     \"APCA-API-KEY-ID\":self._key_id,\n                     \"APCA-API-SECRET-KEY\":self._secret},\n        )\n        self.requests += 1\n        if self.requests > MAX_TOTAL_PAGES:\n            raise MarketFeedError(\"market-data request budget exceeded\")\n        try:\n            with self._opener.open(req, timeout=TIMEOUT_SECONDS) as response:\n                if getattr(response, \"status\", None) != 200:\n                    raise MarketFeedError(\"market-data authentication or provider request failed\")\n                actual_url = response.geturl()\n                if not isinstance(actual_url, str) or actual_url != url:\n                    raise MarketFeedError(\"provider redirected or changed the authenticated endpoint\")\n                body = response.read(MAX_BODY_BYTES + 1)\n        except MarketFeedError:\n            raise\n        except Exception:\n            # Do not chain or print provider errors, tokens, URLs or auth headers.\n            raise MarketFeedError(\"market-data HTTPS read failed\") from None\n        if not isinstance(body, bytes) or len(body) > MAX_BODY_BYTES:\n            raise MarketFeedError(\"market-data response over size cap\")\n        try:\n            document = json.loads(body)\n        except (UnicodeDecodeError, ValueError) as exc:\n            raise MarketFeedError(\"market-data provider response is not JSON\") from exc\n        if not isinstance(document, dict):\n            raise MarketFeedError(\"market-data provider response must be an object\")\n        return document\n\n\ndef _paged(reader: PageReader, *, path: str, params: dict[str, str],\n           symbols: list[str]) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:\n    if path != BARS_PATH:\n        raise MarketFeedError(\"only completed bar pages may be exhaustively paginated\")\n    label = \"bars\"\n    seen_tokens: set[str] = set()\n    pages: list[dict[str, Any]] = []\n    rows: list[dict[str, Any]] = []\n    token: str | None = None\n    while True:\n        if len(pages) >= MAX_PAGES_PER_ENDPOINT:\n            raise MarketFeedError(\"market-data pagination truncated at hard page budget\")\n        query = dict(params)\n        if token is not None:\n            query[\"page_token\"] = token\n        if path not in PATHS:\n            raise MarketFeedError(\"unsupported read endpoint\")\n        response = reader.get(path=path, params=query)\n        if not isinstance(response, dict) or label not in response:\n            raise MarketFeedError(\"provider omitted expected observations section\")\n        _json(response)\n        result = response[label]\n        if not isinstance(result, dict) or not set(result).issubset(set(symbols)):\n            raise MarketFeedError(\"provider observations have invalid symbol scope\")\n        for sym, items in result.items():\n            if not isinstance(items, list):\n                raise MarketFeedError(\"provider symbol observations must be arrays\")\n            for item in items:\n                if not isinstance(item, dict):\n                    raise MarketFeedError(\"provider raw market observation malformed\")\n                rows.append({\"symbol\":sym,\"value\":item})\n                if len(rows) > MAX_ITEMS:\n                    raise MarketFeedError(\"market-data response total rows exceed budget\")\n        page_sha = sha256(_json(response)).hexdigest()\n        pages.append({\"path\":path,\"query\":query,\"response\":response,\n                      \"response_sha256\":page_sha})\n        following = response.get(\"next_page_token\")\n        if following is None or following == \"\":\n            return rows, pages\n        if (not isinstance(following, str) or len(following) > 512 or\n                following in seen_tokens):\n            raise MarketFeedError(\"pagination token cycle or invalid cursor\")\n        seen_tokens.add(following)\n        token = following\n\n\ndef _sample_latest_quotes(\n    reader: PageReader, *, symbols: list[str], feed: str,\n    start: datetime, at: datetime,\n) -> tuple[list[dict[str, Any]], list[dict[str, Any]]]:\n    \"\"\"Exactly one descending, as-of sample per symbol.\n\n    A quote response can legitimately have a next_page_token for older\n    records. We preserve that cursor, DO NOT claim quote-history exhaustion,\n    and intentionally avoid retrieving that older high-frequency history.\n    \"\"\"\n    rows: list[dict[str, Any]] = []\n    pages: list[dict[str, Any]] = []\n    for symbol in symbols:\n        query = {\n            \"symbols\": symbol, \"start\": start.isoformat(),\n            \"end\": at.isoformat(), \"feed\": feed,\n            \"limit\": str(QUOTE_SAMPLE_LIMIT), \"sort\": \"desc\",\n        }\n        response = reader.get(path=QUOTES_PATH, params=query)\n        if (not isinstance(response, dict) or\n                not isinstance(response.get(\"quotes\"), dict) or\n                not set(response[\"quotes\"]).issubset({symbol})):\n            raise MarketFeedError(\"per-symbol provider quote scope invalid\")\n        quote_rows = response[\"quotes\"].get(symbol, [])\n        if not isinstance(quote_rows, list) or len(quote_rows) > QUOTE_SAMPLE_LIMIT:\n            raise MarketFeedError(\"latest quote sample exceeds one record per symbol\")\n        if any(not isinstance(row, dict) for row in quote_rows):\n            raise MarketFeedError(\"provider latest quote record malformed\")\n        continuation = response.get(\"next_page_token\")\n        if (continuation not in (None, \"\") and\n                (not isinstance(continuation, str) or len(continuation) > 512)):\n            raise MarketFeedError(\"malformed older-quote pagination indicator\")\n        if continuation not in (None, \"\") and not quote_rows:\n            raise MarketFeedError(\"no latest quote despite indicated older quote pages\")\n        raw = _json(response)\n        if len(raw) > MAX_BODY_BYTES:\n            raise MarketFeedError(\"provider quote source page exceeds body limit\")\n        pages.append({\n            \"path\": QUOTES_PATH, \"query\": query, \"response\": response,\n            \"response_sha256\": sha256(raw).hexdigest(),\n        })\n        if quote_rows:\n            rows.append({\"symbol\": symbol, \"value\": quote_rows[0]})\n    return rows, pages\n\n\ndef build_paper_snapshot(reader: PageReader, *, slot: dict[str, Any],\n                         symbols: list[str], feed: str = \"iex\"\n                         ) -> dict[str, Any]:\n    \"\"\"Fully page completed bars; sample latest as-of quote for EACH symbol.\n\n    The single-symbol descending sampling is intentionally not an archival\n    capture of every quote. It prevents per-symbol starvation under a shared\n    provider limit while retaining all fetched pages for reproducible replay.\n    \"\"\"\n    validate_slot(slot)\n    if not isinstance(feed,str) or feed not in FEEDS:\n        raise MarketFeedError(\"equities market-data feed must be explicitly iex or sip\")\n    if (not isinstance(symbols, list) or not 1 <= len(symbols) <= MAX_SYMBOLS or\n            any(not isinstance(s,str) or not re.fullmatch(r\"[A-Z][A-Z0-9.]{0,14}\",s) for s in symbols) or\n            len(set(symbols)) != len(symbols)):\n        raise MarketFeedError(\"invalid or oversized paper research symbol list\")\n    at = _utc(slot[\"expected_at\"], \"scheduled expected_at\")\n    if at.second or at.microsecond:\n        raise MarketFeedError(\"paper evidence requires minute-aligned planned scan\")\n    begin_bars = at - timedelta(minutes=3)\n    begin_quotes = at - timedelta(minutes=2)\n    fmt = lambda dt: dt.isoformat()\n    # Alpaca's end boundary can include a bar that starts at 'at' and is\n    # therefore not completed. Exclude that bar explicitly.\n    bar_end = at - timedelta(microseconds=1)\n    bar_rows, bar_pages = _paged(reader,path=BARS_PATH,params={\n        \"symbols\": \",\".join(symbols), \"end\": fmt(bar_end),\n        \"feed\": feed, \"limit\": str(PAGE_LIMIT), \"sort\": \"asc\",\n        \"timeframe\": \"1Min\", \"start\": fmt(begin_bars),\n    },symbols=symbols)\n    quote_rows, quote_pages = _sample_latest_quotes(\n        reader, symbols=symbols, feed=feed, start=begin_quotes, at=at,\n    )\n    if len(bar_rows) + len(quote_rows) > MAX_ITEMS:\n        raise MarketFeedError(\"combined market-data rows exceed source budget\")\n    bars: list[dict[str, Any]] = []\n    bar_seen: set[tuple[str,str]] = set()\n    for row in bar_rows:\n        b, sym = row[\"value\"], row[\"symbol\"]\n        if not isinstance(b, dict) or not {\"t\",\"o\",\"h\",\"l\",\"c\",\"v\"} <= set(b):\n            raise MarketFeedError(\"provider bar missing required fields\")\n        start = _utc(b[\"t\"], \"provider bar start\")\n        end = start + timedelta(minutes=1)\n        if start < begin_bars or end > at:\n            raise MarketFeedError(\"provider returned future, incomplete or out-of-range bar\")\n        unique = (sym,start.isoformat())\n        if unique in bar_seen:\n            raise MarketFeedError(\"duplicate bar across provider pages\")\n        bar_seen.add(unique)\n        volume = b[\"v\"]\n        if isinstance(volume, bool) or not isinstance(volume, int) or volume < 0:\n            raise MarketFeedError(\"provider bar volume invalid\")\n        bars.append({\"symbol\":sym,\"start\":start.isoformat(),\"end\":end.isoformat(),\n                     \"open\":b[\"o\"],\"high\":b[\"h\"],\"low\":b[\"l\"],\n                     \"close\":b[\"c\"],\"volume\":volume})\n    # JSON object field ordering is not data. Provider bar maps can be in\n    # a different order after canonical byte publication/remote restore.\n    # Normalize by REQUESTED universe order, then source timestamp.\n    universe_rank = {symbol: i for i, symbol in enumerate(symbols)}\n    bars.sort(key=lambda bar: (universe_rank[bar[\"symbol\"]], bar[\"start\"]))\n    quote_latest: dict[str,dict[str,Any]] = {}\n    quote_seen: set[tuple[str,str]] = set()\n    for row in quote_rows:\n        q,sym = row[\"value\"],row[\"symbol\"]\n        if not isinstance(q, dict) or not {\"t\",\"bp\",\"ap\",\"bs\",\"as\"} <= set(q):\n            raise MarketFeedError(\"provider quote missing required fields\")\n        when = _utc(q[\"t\"], \"provider quote as-of\")\n        if when < begin_quotes or when > at:\n            raise MarketFeedError(\"future or outside-window provider quote\")\n        key=(sym,when.isoformat())\n        if key in quote_seen:\n            raise MarketFeedError(\"duplicate quote across provider pages\")\n        quote_seen.add(key)\n        for size_name in (\"bs\",\"as\"):\n            if (isinstance(q[size_name],bool) or not isinstance(q[size_name],int)\n                    or q[size_name] < 0):\n                raise MarketFeedError(\"provider quote size invalid\")\n        previous=quote_latest.get(sym)\n        if previous is None or when > _utc(previous[\"observed_at\"], \"prior quote\"):\n            quote_latest[sym]={\"symbol\":sym,\"observed_at\":when.isoformat(),\n                               \"bid\":q[\"bp\"],\"ask\":q[\"ap\"],\n                               \"bid_size\":q[\"bs\"],\"ask_size\":q[\"as\"]}\n    snapshot={\n        \"schema_version\":SNAPSHOT_SCHEMA,\n        **{k:slot[k] for k in (\"workspace_id\",\"run_id\",\"cycle_id\",\n                                \"sequence_no\",\"session_date\")},\n        \"occurred_at\":slot[\"expected_at\"],\n        \"asof_timestamp\":slot[\"expected_at\"],\n        \"source_origin\":\"UNATTESTED_IMPORTED\",\n        \"provider\":\"ALPACA_\"+feed.upper()+\"_HISTORICAL\",\n        \"universe_symbols\":list(symbols),\n        \"bars\":bars,\"quotes\":[quote_latest[s] for s in symbols if s in quote_latest],\n    }\n    try:\n        validate_snapshot(snapshot, slot)\n    except PaperCaptureError as exc:\n        raise MarketFeedError(\"provider records violate offline paper contract\") from exc\n    provenance={\n        \"schema_version\":\"anevum.paper-provider-pages.v1\",\n        \"scope\":{k:slot[k] for k in (\"workspace_id\",\"run_id\",\"cycle_id\",\n                                    \"sequence_no\",\"session_date\")},\n        \"feed\":feed,\"host\":HOST,\n        \"routes\":[BARS_PATH,QUOTES_PATH],\n        \"raw_pages\":bar_pages+quote_pages,\n        \"page_count\":len(bar_pages)+len(quote_pages),\n        \"bar_records\":len(bar_rows),\n        \"quote_records\":len(quote_rows),\n        \"response_pagination_exhausted\":False,\n        \"bar_pagination_exhausted\":True,\n        \"quote_sampling_mode\":QUOTE_SAMPLING_MODE,\n        \"quote_history_exhausted\":False,\n        \"quote_symbols_requested\":list(symbols),\n        \"missing_bar_symbols\":sorted(set(symbols)-{b[\"symbol\"] for b in bars}),\n        \"missing_quote_symbols\":sorted(set(symbols)-set(quote_latest)),\n        \"snapshot_sha256\":sha256(_json(snapshot)).hexdigest(),\n        \"independently_provider_attested\":False,\n        \"external_schedule_attested\":False,\n        \"data_state\":\"AWAITING_EVIDENCE\",\n        \"broker_calls\":0,\n    }\n    if len(_json(provenance)) > MAX_RESPONSE_BYTES:\n        raise MarketFeedError(\"combined provider evidence over budget\")\n    return {\"snapshot\":snapshot,\"provenance\":provenance,\n            \"paper_only\":True,\"broker_calls\":0,\"evidence_state\":\"AWAITING_EVIDENCE\"}\n","/projects/rhen/source/research/outcomes.py":"\"\"\"RHEN V5 Research R1: deterministic PAPER-only counterfactual maturation.\n\nNever fetches broker data, sends an order, promotes a strategy, or asserts that\ninput price observations are independently complete/archived. Qualified,\nrejected and unmeasurable candidates receive identical maturation treatment.\n\"\"\"\nfrom __future__ import annotations\n\nfrom datetime import datetime, timedelta, timezone\nfrom decimal import Decimal, InvalidOperation\nfrom hashlib import sha256\nimport json\nimport re\nfrom typing import Any, Mapping\n\nfrom next_rhen.evidence_journal import validate_cycle, EvidenceContractError\n\nSCHEMA = \"anevum.rhen.paper-outcomes.v1\"\nWINDOWS = (5, 15, 60)\nHEX64 = re.compile(r\"^[0-9a-f]{64}$\")\nOBS_KEYS = frozenset({\"observed_at\", \"close\", \"source_sha256\"})\nMAX_PRICE = Decimal(\"1000000000000\")\n\n\nclass OutcomeContractError(ValueError):\n    \"\"\"Untrusted or temporally inconsistent paper-market observation.\"\"\"\n\n\ndef _utc(value: Any, field: str) -> datetime:\n    if not isinstance(value, str) or not value:\n        raise OutcomeContractError(f\"{field} requires ISO timezone timestamp\")\n    try:\n        stamp = datetime.fromisoformat(value.replace(\"Z\", \"+00:00\"))\n    except ValueError as exc:\n        raise OutcomeContractError(f\"{field} timestamp invalid\") from exc\n    if stamp.tzinfo is None:\n        raise OutcomeContractError(f\"{field} timezone missing\")\n    return stamp.astimezone(timezone.utc)\n\n\ndef _price(value: Any, field: str) -> Decimal:\n    if isinstance(value, bool) or not isinstance(value, (int, float)):\n        raise OutcomeContractError(f\"{field} must be numeric\")\n    try:\n        result = Decimal(str(value))\n    except InvalidOperation as exc:\n        raise OutcomeContractError(f\"{field} price invalid\") from exc\n    if not result.is_finite() or not Decimal(0) < result < MAX_PRICE:\n        raise OutcomeContractError(f\"{field} price nonfinite or nonpositive\")\n    return result\n\n\ndef _point(record: Any, field: str) -> tuple[datetime, Decimal, str]:\n    if not isinstance(record, dict) or set(record) != OBS_KEYS:\n        raise OutcomeContractError(f\"{field} observation requires exact source fields\")\n    at = _utc(record[\"observed_at\"], field)\n    close = _price(record[\"close\"], field)\n    ref = record[\"source_sha256\"]\n    if not isinstance(ref, str) or not HEX64.fullmatch(ref):\n        raise OutcomeContractError(f\"{field} immutable source SHA is invalid\")\n    return at, close, ref\n\n\ndef mature_cycle(\n    cycle: Mapping[str, Any],\n    *,\n    anchor_prices: Mapping[str, Any],\n    horizon_prices: Mapping[str, Any],\n    evaluated_at: str,\n) -> dict[str, Any]:\n    \"\"\"Derive 5/15/60m gross long-reference returns on supplied source records.\n\n    The cycle's candidate population is the only permissible symbol universe.\n    Input points are external, UNVERIFIED observations with exact timestamp and\n    SHA references. An output of OBSERVED_UNATTESTED is NOT valid broker P&L,\n    not a proved historical quote tape, and not a validation/holdout result.\n    \"\"\"\n    try:\n        cycle_bytes = validate_cycle(cycle)\n    except EvidenceContractError as exc:\n        raise OutcomeContractError(\"source decision cycle contract rejected\") from exc\n    observed = _utc(evaluated_at, \"evaluated_at\")\n    decided = _utc(cycle[\"occurred_at\"], \"cycle.occurred_at\")\n    if observed < decided:\n        raise OutcomeContractError(\"evaluation timestamp precedes decision\")\n    symbols = set(cycle[\"universe_symbols\"])\n    if not isinstance(anchor_prices, dict) or not isinstance(horizon_prices, dict):\n        raise OutcomeContractError(\"anchor/horizon collections must be records\")\n    if set(anchor_prices) - symbols or set(horizon_prices) - symbols:\n        raise OutcomeContractError(\"input contains symbol outside recorded full population\")\n\n    anchor: dict[str, tuple[datetime, Decimal, str]] = {}\n    for symbol, raw in anchor_prices.items():\n        point = _point(raw, f\"anchor:{symbol}\")\n        if not decided - timedelta(minutes=3) <= point[0] <= decided:\n            raise OutcomeContractError(\"anchor timestamp is future or too stale\")\n        anchor[symbol] = point\n    horizons: dict[str, dict[int, tuple[datetime, Decimal, str]]] = {}\n    for symbol, values in horizon_prices.items():\n        if not isinstance(values, dict) or set(values) - {str(w) for w in WINDOWS}:\n            raise OutcomeContractError(\"horizon set is not one of 5,15,60m\")\n        parsed = {}\n        for k, record in values.items():\n            window = int(k)\n            stamp, price, ref = _point(record, f\"horizon:{symbol}:{window}\")\n            target = decided + timedelta(minutes=window)\n            if stamp != target:\n                raise OutcomeContractError(\"future price not from exact matured horizon\")\n            if stamp > observed:\n                raise OutcomeContractError(\"future price not yet observable at evaluated_at\")\n            parsed[window] = (stamp, price, ref)\n        horizons[symbol] = parsed\n\n    results = []\n    counts = {\n        \"OBSERVED_UNATTESTED\": 0,\n        \"NOT_YET_DUE\": 0,\n        \"MISSING_ANCHOR\": 0,\n        \"MISSING_HORIZON\": 0,\n    }\n    for candidate in cycle[\"candidates\"]:\n        symbol = candidate[\"symbol\"]\n        entry = anchor.get(symbol)\n        for minutes in WINDOWS:\n            target = decided + timedelta(minutes=minutes)\n            forward = horizons.get(symbol, {}).get(minutes)\n            status = (\n                \"NOT_YET_DUE\" if observed < target\n                else \"MISSING_ANCHOR\" if entry is None\n                else \"MISSING_HORIZON\" if forward is None\n                else \"OBSERVED_UNATTESTED\"\n            )\n            result = {\n                \"symbol\": symbol,\n                \"recorded_decision\": candidate[\"decision\"],\n                \"horizon_minutes\": minutes,\n                \"due_at\": target.isoformat().replace(\"+00:00\", \"Z\"),\n                \"status\": status,\n                \"gross_long_reference_bps\": None,\n                \"anchor_sha256\": entry[2] if entry else None,\n                \"horizon_sha256\": forward[2] if forward else None,\n            }\n            if status == \"OBSERVED_UNATTESTED\":\n                value = (forward[1] / entry[1] - Decimal(1)) * Decimal(10000)\n                result[\"gross_long_reference_bps\"] = float(round(value, 6))\n            results.append(result)\n            counts[status] += 1\n\n    envelope = {\n        \"schema_version\": SCHEMA,\n        \"workspace_id\": cycle[\"workspace_id\"],\n        \"run_id\": cycle[\"run_id\"],\n        \"cycle_id\": cycle[\"cycle_id\"],\n        \"sequence_no\": cycle[\"sequence_no\"],\n        \"decision_cycle_sha256\": sha256(cycle_bytes).hexdigest(),\n        \"execution_mode\": \"PAPER_RESEARCH_ONLY\",\n        \"evaluated_at\": observed.isoformat().replace(\"+00:00\", \"Z\"),\n        \"source_quality\": \"AWAITING_INDEPENDENT_ATTESTATION\",\n        \"execution_costs_included\": False,\n        \"orders_or_positions\": False,\n        \"alpha_validated\": False,\n        \"strategy_promotion_allowed\": False,\n        \"horizons\": list(WINDOWS),\n        \"candidate_count\": len(cycle[\"candidates\"]),\n        \"status_counts\": counts,\n        \"results\": results,\n    }\n    # Immutable content digest allows offline comparison. This is not evidence\n    # that an external broker, archive, scheduler or replay engine verified it.\n    raw = json.dumps(envelope, sort_keys=True, separators=(\",\", \":\"),\n                     allow_nan=False).encode(\"utf-8\")\n    envelope[\"content_sha256\"] = sha256(raw).hexdigest()\n    return envelope\n","/projects/rhen/source/replay/scorecard.py":"\"\"\"RHEN V5 Replay R1: bounded cost-assumption scorecard from R1 outcomes.\n\nPure CPU work on unverified hypothetical marks. It does NOT backtest execution,\nestimate realizable alpha, fill orders, promote strategies or contact brokers.\n\"\"\"\nfrom __future__ import annotations\n\nfrom datetime import datetime, timedelta, timezone\nfrom decimal import Decimal, InvalidOperation\nfrom hashlib import sha256\nimport json\nimport math\nimport re\nfrom typing import Any, Mapping\n\nfrom next_rhen.research.outcomes import SCHEMA as OUTCOMES_SCHEMA, WINDOWS\n\nSCHEMA = \"anevum.rhen.paper-cost-scorecard.v1\"\n_COST_KEYS = frozenset({\n    \"spread_bps\", \"entry_slippage_bps\", \"exit_slippage_bps\", \"roundtrip_fees_bps\",\n})\n_RESULT_KEYS = frozenset({\n    \"symbol\", \"recorded_decision\", \"horizon_minutes\", \"due_at\", \"status\",\n    \"gross_long_reference_bps\", \"anchor_sha256\", \"horizon_sha256\",\n})\n_STATUSES = frozenset({\n    \"OBSERVED_UNATTESTED\", \"NOT_YET_DUE\", \"MISSING_ANCHOR\", \"MISSING_HORIZON\",\n})\n_DECISIONS = frozenset({\"QUALIFIED\", \"REJECTED\", \"UNMEASURABLE\"})\n_SOURCE_SHA = re.compile(r\"^[0-9a-f]{64}$\")\n\n\nclass ReplayContractError(ValueError):\n    \"\"\"Unverified, tampered or insufficient research input cannot be scored.\"\"\"\n\n\ndef _digest(value: Mapping[str, Any]) -> str:\n    return sha256(json.dumps(value, sort_keys=True, separators=(\",\", \":\"),\n                            allow_nan=False).encode(\"utf-8\")).hexdigest()\n\n\ndef _utc_stamp(value: Any, field: str) -> datetime:\n    if not isinstance(value, str) or not value.endswith(\"Z\"):\n        raise ReplayContractError(f\"{field} requires a canonical UTC timestamp\")\n    try:\n        at = datetime.fromisoformat(value[:-1] + \"+00:00\")\n    except ValueError as exc:\n        raise ReplayContractError(f\"{field} timestamp invalid\") from exc\n    if at.tzinfo is None or at.utcoffset() != timedelta(0) or (\n        at.isoformat().replace(\"+00:00\", \"Z\") != value\n    ):\n        raise ReplayContractError(f\"{field} timestamp is not canonical UTC\")\n    return at\n\n\ndef _cost(value: Any, key: str) -> Decimal:\n    if isinstance(value, bool) or not isinstance(value, (int, float)):\n        raise ReplayContractError(f\"{key} must be a numeric bounded cost\")\n    try:\n        cost = Decimal(str(value))\n    except InvalidOperation as exc:\n        raise ReplayContractError(f\"{key} invalid cost\") from exc\n    if not cost.is_finite() or not Decimal(0) <= cost <= Decimal(1000):\n        raise ReplayContractError(f\"{key} is negative, nonfinite or unreasonable\")\n    return cost\n\n\ndef score_paper_horizons(outcomes: Mapping[str, Any], *, cost_model: Mapping[str, Any]) -> dict:\n    \"\"\"Model costs on independently UNATTESTED gross long-reference marks.\n\n    Returns no strategy PASS, no equity curve, no trade P&L and no order\n    authority. Missing outcome rows never become zero-P&L observations.\n    \"\"\"\n    if not isinstance(outcomes, dict):\n        raise ReplayContractError(\"outcomes must be an immutable replay document\")\n    if (outcomes.get(\"schema_version\") != OUTCOMES_SCHEMA or\n            outcomes.get(\"execution_mode\") != \"PAPER_RESEARCH_ONLY\" or\n            outcomes.get(\"source_quality\") != \"AWAITING_INDEPENDENT_ATTESTATION\" or\n            outcomes.get(\"strategy_promotion_allowed\") is not False or\n            outcomes.get(\"alpha_validated\") is not False or\n            outcomes.get(\"execution_costs_included\") is not False or\n            outcomes.get(\"orders_or_positions\") is not False or\n            outcomes.get(\"horizons\") != list(WINDOWS)):\n        raise ReplayContractError(\"paper source or research authorization contract violated\")\n    digest = outcomes.get(\"content_sha256\")\n    original = {key: value for key, value in outcomes.items() if key != \"content_sha256\"}\n    try:\n        computed_digest = _digest(original)\n    except (ValueError, TypeError) as exc:\n        raise ReplayContractError(\"malformed outcome document\") from exc\n    if not isinstance(digest, str) or digest != computed_digest:\n        raise ReplayContractError(\"canonical outcome digest mismatch\")\n    if not isinstance(cost_model, dict) or set(cost_model) != _COST_KEYS:\n        raise ReplayContractError(\"exact declared cost assumptions required\")\n    costs = {key: _cost(cost_model[key], key) for key in sorted(_COST_KEYS)}\n    roundtrip = sum(costs.values(), Decimal(0))\n    records = outcomes.get(\"results\")\n    size = outcomes.get(\"candidate_count\")\n    if (not isinstance(records, list) or isinstance(size, bool)\n            or not isinstance(size, int) or not 0 <= size <= 5000\n            or len(records) != size * len(WINDOWS)):\n        raise ReplayContractError(\"full candidate horizon grid is incomplete\")\n\n    evaluated = _utc_stamp(outcomes.get(\"evaluated_at\"), \"evaluated_at\")\n    decision_at: datetime | None = None\n    decisions_by_symbol: dict[str, str] = {}\n    anchors_by_symbol: dict[str, str | None] = {}\n    seen: set[tuple[str, int]] = set()\n    per_horizon: dict[int, dict] = {\n        minutes: {\"observed\": 0, \"missing\": 0, \"gross\": Decimal(0),\n                  \"net\": Decimal(0), \"by_decision\": {d: 0 for d in _DECISIONS}}\n        for minutes in WINDOWS\n    }\n    statuses = {key: 0 for key in _STATUSES}\n    priced = []\n    for result in records:\n        if not isinstance(result, dict) or set(result) != _RESULT_KEYS:\n            raise ReplayContractError(\"horizon record has unexpected or missing fields\")\n        symbol, minutes = result[\"symbol\"], result[\"horizon_minutes\"]\n        if (not isinstance(symbol, str) or not symbol or\n                isinstance(minutes, bool) or minutes not in WINDOWS or\n                (symbol, minutes) in seen):\n            raise ReplayContractError(\"duplicate or malformed symbol/horizon\")\n        seen.add((symbol, minutes))\n        status, decision = result[\"status\"], result[\"recorded_decision\"]\n        if status not in _STATUSES or decision not in _DECISIONS:\n            raise ReplayContractError(\"unknown observation or decision state\")\n        due = _utc_stamp(result[\"due_at\"], \"due_at\")\n        inferred_decision_at = due - timedelta(minutes=minutes)\n        if decision_at is None:\n            decision_at = inferred_decision_at\n        elif inferred_decision_at != decision_at:\n            raise ReplayContractError(\"due_at not aligned to the original decision cycle\")\n        if (status == \"NOT_YET_DUE\") != (evaluated < due):\n            raise ReplayContractError(\"observation maturity disagrees with evaluated_at\")\n        if symbol in decisions_by_symbol and decisions_by_symbol[symbol] != decision:\n            raise ReplayContractError(\"recorded decision changed across horizons\")\n        decisions_by_symbol[symbol] = decision\n        anchor_ref, future_ref = result[\"anchor_sha256\"], result[\"horizon_sha256\"]\n        for source_name, source_ref in ((\"anchor\", anchor_ref), (\"horizon\", future_ref)):\n            if source_ref is not None and (\n                not isinstance(source_ref, str) or\n                not _SOURCE_SHA.fullmatch(source_ref)\n            ):\n                raise ReplayContractError(f\"{source_name} SHA256 reference invalid\")\n        if symbol in anchors_by_symbol and anchors_by_symbol[symbol] != anchor_ref:\n            raise ReplayContractError(\"anchor source changed across horizons\")\n        anchors_by_symbol[symbol] = anchor_ref\n        if status == \"NOT_YET_DUE\" and future_ref is not None:\n            raise ReplayContractError(\"future source cannot be observed before maturity\")\n        if status == \"MISSING_ANCHOR\" and anchor_ref is not None:\n            raise ReplayContractError(\"missing anchor status has an anchor source\")\n        if status == \"MISSING_HORIZON\" and (anchor_ref is None or future_ref is not None):\n            raise ReplayContractError(\"missing horizon status has inconsistent sources\")\n        statuses[status] += 1\n        b = per_horizon[minutes]\n        is_observed = status == \"OBSERVED_UNATTESTED\"\n        gross = result[\"gross_long_reference_bps\"]\n        if is_observed:\n            if (not isinstance(gross, (int, float)) or isinstance(gross, bool) or\n                    not math.isfinite(gross) or gross < -10000):\n                raise ReplayContractError(\"invalid observed hypothetical gross mark\")\n            if anchor_ref is None or future_ref is None:\n                raise ReplayContractError(\"observed mark missing referenced source\")\n            net = Decimal(str(gross)) - roundtrip\n            b[\"observed\"] += 1\n            b[\"gross\"] += Decimal(str(gross))\n            b[\"net\"] += net\n            b[\"by_decision\"][decision] += 1\n            modeled = float(round(net, 6))\n        else:\n            if gross is not None:\n                raise ReplayContractError(\"missing source may not claim a realized mark\")\n            b[\"missing\"] += 1\n            modeled = None\n        priced.append({\n            \"symbol\": symbol, \"recorded_decision\": decision,\n            \"horizon_minutes\": minutes, \"source_status\": status,\n            \"hypothetical_gross_bps\": gross if is_observed else None,\n            \"hypothetical_net_after_assumed_cost_bps\": modeled,\n        })\n    if statuses != outcomes.get(\"status_counts\") or len(seen) != len(records):\n        raise ReplayContractError(\"count or uniqueness integrity mismatch\")\n    # Require the same full candidate population at every horizon.\n    groups = [{symbol for (symbol, h) in seen if h == minutes} for minutes in WINDOWS]\n    if not all(group == groups[0] and len(group) == size for group in groups):\n        raise ReplayContractError(\"horizon-specific survivor filtering is forbidden\")\n\n    stats = {}\n    for minutes, values in per_horizon.items():\n        count = values[\"observed\"]\n        stats[str(minutes)] = {\n            \"observed_candidates\": count,\n            \"missing_candidates\": values[\"missing\"],\n            \"by_recorded_decision\": {k: values[\"by_decision\"][k] for k in sorted(_DECISIONS)},\n            \"mean_gross_reference_bps\": float(round(values[\"gross\"]/count, 6)) if count else None,\n            \"mean_net_assumption_bps\": float(round(values[\"net\"]/count, 6)) if count else None,\n        }\n    return {\n        \"schema_version\": SCHEMA,\n        \"source_outcome_sha256\": digest,\n        \"workspace_id\": outcomes[\"workspace_id\"],\n        \"run_id\": outcomes[\"run_id\"],\n        \"cycle_id\": outcomes[\"cycle_id\"],\n        \"evaluation_mode\": \"OFFLINE_PAPER_COUNTERFACTUAL\",\n        \"source_quality\": \"AWAITING_INDEPENDENT_ATTESTATION\",\n        \"cost_assumptions_bps\": {k: float(v) for k, v in costs.items()},\n        \"modeled_roundtrip_cost_bps\": float(roundtrip),\n        \"horizon_summary\": stats,\n        \"hypothetical_marks\": priced,\n        \"broker_order_authority\": False,\n        \"net_execution_pnl\": None,\n        \"validated_alpha\": False,\n        \"promotion_allowed\": False,\n    }\n"});
